export function findNlpCorporaProfilesById(id: string): NlpCorpusRecord | undefined {
  return NLP_CORPORA_DATABASE.find(item => item.id === id);
}

export function getAllNlpCorporaProfilesRecords(): NlpCorpusRecord[] {
  return NLP_CORPORA_DATABASE;
}

export function filterNlpCorporaProfilesByPredicate(predicate: (item: NlpCorpusRecord) => boolean): NlpCorpusRecord[] {
  return NLP_CORPORA_DATABASE.filter(predicate);
}

export function countNlpCorporaProfilesRecords(): number {
  return NLP_CORPORA_DATABASE.length;
}
